chapterList.JSParser:
function functionName(config, params, result)
{
	let list = result.list;
	if(list != undefined && list.length>5)
	{
		// 有时顺序不对，逆序
		let id1 = undefined;
		let id2 = undefined;

		let len = list.length;
		for(i=0; i<len; i++)
		{
			let url = list[i].url;
			if(url.indexOf('-')>0)
			{
				if(id1 == undefined)
					id1 = url.match(/(\d+)/)[1];
				else
					id2 = url.match(/(\d+)/)[1];
			}
			if(id2 != undefined)
				break;
		}

		if(id1 != undefined && id2 != undefined && parseInt(id1[1]) > parseInt(id2[1]))
			result.list = list.reverse();
	}

	return result;
}

